"""One-shot, development-only SQLite snapshot import into an empty PG schema.

This is deliberately not called by the application or deployment startup.
"""
from __future__ import annotations

import argparse
import os
import re
import sqlite3
import sys
from pathlib import Path

import psycopg
from psycopg import sql


def postgres_ddl(statement: str) -> str:
    statement = re.sub(
        r"\bINTEGER\s+PRIMARY\s+KEY\s+AUTOINCREMENT\b",
        "INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY",
        statement,
        flags=re.IGNORECASE,
    )
    if re.search(r"\bAUTOINCREMENT\b", statement, re.IGNORECASE):
        raise ValueError("Unsupported SQLite AUTOINCREMENT declaration.")
    if re.search(r"\bWITHOUT\s+ROWID\b", statement, re.IGNORECASE):
        raise ValueError("WITHOUT ROWID tables need an explicit migration mapping.")
    return statement


def migrate(source_path: Path, schema_path: Path, schema: str) -> dict[str, int]:
    if os.environ.get("REPLIT_ENVIRONMENT") != "development":
        raise RuntimeError("Refusing to run unless REPLIT_ENVIRONMENT=development.")
    if os.environ.get("MIGRATION_TARGET") != "development":
        raise RuntimeError("Set MIGRATION_TARGET=development for this rehearsal.")
    if schema == "public" or not re.fullmatch(r"[a-zA-Z_][a-zA-Z0-9_]*", schema):
        raise RuntimeError("Use a dedicated, non-public PostgreSQL schema.")
    dsn = os.environ.get("DATABASE_URL")
    if not dsn:
        raise RuntimeError("The managed development DATABASE_URL is unavailable.")
    if not source_path.is_file():
        raise FileNotFoundError(source_path)

    source = sqlite3.connect(f"file:{source_path.resolve()}?mode=ro", uri=True)
    source.row_factory = sqlite3.Row
    schema_source = sqlite3.connect(
        f"file:{schema_path.resolve()}?mode=ro", uri=True
    )
    schema_source.row_factory = sqlite3.Row
    fk_errors = source.execute("PRAGMA foreign_key_check").fetchall()
    if fk_errors:
        raise RuntimeError(f"SQLite source has {len(fk_errors)} foreign-key violations.")

    table_sql = schema_source.execute(
        "SELECT name, sql FROM sqlite_master "
        "WHERE type='table' AND sql IS NOT NULL AND name NOT LIKE 'sqlite_%' "
        "ORDER BY name"
    ).fetchall()
    index_sql = schema_source.execute(
        "SELECT sql FROM sqlite_master WHERE type='index' AND sql IS NOT NULL ORDER BY name"
    ).fetchall()
    if not table_sql:
        raise RuntimeError("The source SQLite database contains no application tables.")

    counts: dict[str, int] = {}
    with psycopg.connect(dsn) as target:
        with target.cursor() as cursor:
            cursor.execute(
                "SELECT COUNT(*) FROM information_schema.tables "
                "WHERE table_schema = %s AND table_type = 'BASE TABLE'",
                (schema,),
            )
            if cursor.fetchone()[0]:
                raise RuntimeError(f"Refusing to import into non-empty schema {schema!r}.")
            cursor.execute(sql.SQL("CREATE SCHEMA {}").format(sql.Identifier(schema)))
            cursor.execute(sql.SQL("SET search_path TO {}").format(sql.Identifier(schema)))

            for table in table_sql:
                cursor.execute(postgres_ddl(table["sql"]))

            source_tables = {
                row["name"] for row in source.execute(
                    "SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%'"
                )
            }
            target_tables = {table["name"] for table in table_sql}
            unknown_tables = source_tables - target_tables
            if unknown_tables:
                raise RuntimeError(
                    "Backup contains tables absent from the current schema: "
                    + ", ".join(sorted(unknown_tables))
                )

            for table in table_sql:
                name = table["name"]
                quoted_name = name.replace('"', '""')
                source_columns = {
                    row["name"] for row in source.execute(f'PRAGMA table_info("{quoted_name}")')
                } if name in source_tables else set()
                columns = [
                    row["name"] for row in schema_source.execute(
                        f'PRAGMA table_info("{quoted_name}")'
                    )
                    if row["name"] in source_columns
                ]
                rows = source.execute(
                    f'SELECT * FROM "{quoted_name}"'
                ).fetchall() if name in source_tables else []
                if rows:
                    insert = sql.SQL("INSERT INTO {} ({}) VALUES ({})").format(
                        sql.Identifier(name),
                        sql.SQL(", ").join(map(sql.Identifier, columns)),
                        sql.SQL(", ").join(sql.Placeholder() for _ in columns),
                    )
                    cursor.executemany(insert, [tuple(row) for row in rows])
                counts[name] = len(rows)
                id_columns = [
                    row["name"] for row in schema_source.execute(
                        f'PRAGMA table_info("{quoted_name}")'
                    )
                    if row["pk"] == 1 and row["type"].upper() == "INTEGER"
                    and row["name"] in columns
                ]
                for id_column in id_columns:
                    cursor.execute(
                        "SELECT pg_get_serial_sequence(%s, %s)",
                        (f"{schema}.{name}", id_column),
                    )
                    sequence = cursor.fetchone()[0]
                    if sequence and rows:
                        maximum = max(int(row[id_column]) for row in rows if row[id_column] is not None)
                        cursor.execute(
                            "SELECT setval(%s::regclass, %s, true)",
                            (sequence, maximum),
                        )
            for index in index_sql:
                cursor.execute(index["sql"])
            cursor.execute("SET CONSTRAINTS ALL IMMEDIATE")
            cursor.execute(
                "SELECT COUNT(*) FROM information_schema.tables "
                "WHERE table_schema = %s AND table_type = 'BASE TABLE'",
                (schema,),
            )
            if cursor.fetchone()[0] != len(table_sql):
                raise RuntimeError("Target table count does not match the SQLite source.")
    source.close()
    schema_source.close()
    return counts


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("sqlite_backup", type=Path)
    parser.add_argument(
        "--schema-source",
        type=Path,
        default=Path(__file__).resolve().parent / "data" / "volleyball.sqlite3",
        help="Read-only current development SQLite DB used for schema only.",
    )
    parser.add_argument(
        "--schema",
        default="wombats_migration_rehearsal",
        help="Dedicated PostgreSQL schema; public is never allowed.",
    )
    args = parser.parse_args()
    counts = migrate(args.sqlite_backup, args.schema_source, args.schema)
    print(f"Imported {sum(counts.values())} rows across {len(counts)} tables into {args.schema}.")
    print("The source SQLite file was opened read-only; no production database was used.")
    return 0


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except Exception as error:
        print(f"Migration rehearsal failed: {error}", file=sys.stderr)
        raise SystemExit(1)
